"""Shared full-screen control for the two views. F or the button = full screen. No arrow-key paging:
inside the demo page the two views toggle with a button above them. When a view runs inside the demo
page (an iframe), its own button hides and F asks the page to put the whole view block in full screen."""

NAV = """<button id="fs" title="%%FS%% (F)" aria-label="%%FS%%">⛶</button><style>#fs{position:fixed;right:14px;bottom:12px;z-index:9;border:1px solid #dfe6e6;background:#fff;color:#5d7178;border-radius:8px;width:34px;height:34px;font-size:17px;cursor:pointer;opacity:.55}#fs:hover{opacity:1}:fullscreen #fs{display:none}body.flow #fs,body.embedded #fs{display:none}</style><script>(function(){var emb=false;try{emb=window.self!==window.top;}catch(e){emb=true;}if(emb)document.body.classList.add('embedded');function fs(){if(emb){try{window.parent.postMessage({vista:'fs'},location.origin);}catch(e){}return;}var d=document.documentElement;try{if(!document.fullscreenElement)d.requestFullscreen();else document.exitFullscreen();}catch(e){}}document.getElementById('fs').onclick=fs;document.addEventListener('keydown',function(e){if((e.key==='f'||e.key==='F')&&!e.metaKey&&!e.ctrlKey&&!e.altKey)fs();});})();</script>"""
